function auditFollowupFiniteReadout(get, codec, treeHash) {
  const source=JSON.parse(get("source-before.json"));
  const result=JSON.parse(get("finite-results.json"));
  const assert=(v,m)=>{if(!v)throw Error(m)};
  assert(get("source-before.json")===get("source-after.json"),"source map changed");
  assert(get("environment-before.json")===get("environment-after.json"),"environment changed");
  assert(get("test-temp-before.json")===get("test-temp-after.json"),"test root changed");
  const sha=s=>codec.sha256Latin1(codec.utf8Bytes(s));
  const entities=s=>s.replace(/&(#x[0-9A-Fa-f]+|#[0-9]+|amp|lt|gt|quot|apos);/g,(_,v)=>{
    if(v[0]==="#")return String.fromCodePoint(v[1]==="x"?parseInt(v.slice(2),16):parseInt(v.slice(1),10));
    return {amp:"&",lt:"<",gt:">",quot:'"',apos:"'"}[v];
  });
  const attrs=s=>{const a={};for(const m of s.matchAll(/([A-Za-z_][A-Za-z_0-9.-]*)="([^"]*)"/g)){
    assert(!(m[1] in a),"duplicate attribute");a[m[1]]=entities(m[2]);}return a;};
  const cohorts=[];let total=0;let phaseCount=0;let failureCount=0;let sourceOriginCount=0;
  for(const expected of result.cohorts){
    const name=expected.cohort;
    const cap=JSON.parse(get(name+"/pytest-capture.json"));
    const xml=get(name+"/junit.xml");
    assert(!/<!DOCTYPE|<!ENTITY|<!\[CDATA\[/.test(xml),"unexpected XML constructs");
    const suite=[...xml.matchAll(/<testsuite\s+([^>]+)>/g)];
    assert(suite.length===1,"exact suite");
    const sa=attrs(suite[0][1]);
    const cases=[...xml.matchAll(/<testcase\s+([^>]*?)(?:\/>|>([\s\S]*?)<\/testcase>)/g)].map(m=>({
      attributes:attrs(m[1]), outcome:/<(failure|error)\b/.test(m[2]||"")?"failed":/<skipped\b/.test(m[2]||"")?"skipped":"passed",
      body:m[2]||""
    }));
    assert(cap.collection_admitted===true&&cap.error===null,"collection admission");
    assert(cap.source_sha===source.source_sha&&cap.source_tree===source.source_tree,"capture source identity");
    assert(cases.length===Number(sa.tests)&&cases.length===cap.collection.length&&cases.length===expected.expected_cases,"actual case count");
    assert(cap.reports.length===cases.length*3,"three phases each");
    assert(new Set(cap.collection.map(r=>r.nodeid)).size===cases.length,"unique collected nodes");
    const seen=new Set();const phaseDistribution={passed:0,failed:0,skipped:0};const failures=[];
    for(let i=0;i<cases.length;i++){
      const row=cap.collection[i];const c=cases[i];
      const node=row.nodeid;const summary=expected.cases[i];
      assert(summary.nodeid===node&&JSON.stringify(summary.junit.attributes)===JSON.stringify(c.attributes),"JUnit exact row attributes/order");
      const params=node.indexOf("[");
      const head=params<0?node:node.slice(0,params);const tail=params<0?"":node.slice(params);
      const names=head.split("::");names[0]=names[0].replace(/\.py$/,"").replaceAll("/",".");
      assert(c.attributes.classname===names.slice(0,-1).join(".")&&c.attributes.name===names.at(-1)+tail,"independent ASCII JUnit address");
      const key=c.attributes.classname+"\0"+c.attributes.name;assert(!seen.has(key),"duplicate JUnit identity");seen.add(key);
      const phases=cap.reports.filter(p=>p.nodeid===node);
      assert(phases.map(p=>p.when).join(",")==="setup,call,teardown","actual phase order");
      for(const phase of phases){
        assert(phase.outcome in phaseDistribution&&!phase.wasxfail&&!phase.longrepr_censored,"phase outcome/censor");
        phaseDistribution[phase.outcome]++;
        const text=phase.longrepr||"";
        assert(codec.utf8Bytes(text).length===phase.longrepr_bytes&&sha(text)===phase.longrepr_sha256,"full traceback hash");
      }
      const outcome=phases.some(p=>p.outcome==="failed")?"failed":phases.some(p=>p.outcome==="skipped")?"skipped":"passed";
      assert(outcome===c.outcome&&summary.outcome===outcome,"case result bijection");
      if(outcome==="failed")failures.push({nodeid:node,phase:phases.find(p=>p.outcome==="failed").when,traceback:phases.find(p=>p.outcome==="failed").longrepr});
      assert(row.function.origin==="candidate"&&source.files[row.function.path].sha256===row.function.sha256,"test source hash");
      for(const list of Object.values(row.fixtures))for(const f of list){
        if(f.source.origin==="candidate")assert(source.files[f.source.path].sha256===f.source.sha256,"fixture source hash");
        assert(sha(cap.complete_definition_asts[f.source.complete_definition_ast_sha256])===f.source.complete_definition_ast_sha256,"fixture full AST hash");
      }
      assert(sha(cap.complete_definition_asts[row.function.complete_definition_ast_sha256])===row.function.complete_definition_ast_sha256,"test full AST hash");
    }
    assert(Number(sa.failures)+Number(sa.errors)===failures.length&&Number(sa.skipped)===0,"suite actual failures/skips");
    for(const row of Object.values(cap.source_origins)){assert(source.files[row.path]?.sha256===row.sha256,"loaded product origin");sourceOriginCount++;}
    for(const [hash,ast] of Object.entries(cap.complete_definition_asts))assert(hash===sha(ast),"all full AST hashes");
    assert(failures.length===expected.counts.failed&&cases.length-failures.length===expected.counts.passed,"reported counts");
    cohorts.push({cohort:name,cases:cases.length,passed:cases.length-failures.length,failed:failures.length,skipped:0,phases:phaseDistribution,complete_definition_asts:Object.keys(cap.complete_definition_asts).length,actual_source_origins:Object.keys(cap.source_origins).length,failed_cases:failures,all_cases:expected.cases});
    total+=cases.length;phaseCount+=cap.reports.length;failureCount+=failures.length;
  }
  const commands=JSON.parse(get("commands.json"));
  assert(get("commands.json")===get("steps.json"),"command ledger differs");
  for(const c of commands){assert(c.group_cleanup.passed===true&&c.group_cleanup.no_live_members_in_original_group===true,"owned group");
    const text=get(c.name+".log");assert(codec.utf8Bytes(text).length===c.log_bytes&&sha(text)===c.log_sha256,"command log");}
  const env=JSON.parse(get("environment-before.json"));
  const tree=treeHash(Object.entries(source.files).map(([path,v])=>({path,mode:v.mode,type:"blob",sha:v.git_blob})));
  assert(tree===source.source_tree,"complete source tree");
  return {audit_passed:true,original_workload_passed:JSON.parse(get("job-outcome.json")).passed===true,source_sha:source.source_sha,source_tree:tree,harness_sha:source.harness_sha,source_files:Object.keys(source.files).length,harness_files:Object.keys(source.harness_files).length,actual_cases:total,passed:total-failureCount,failed:failureCount,skipped:0,incomplete:0,actual_phases:phaseCount,source_origins_checked:sourceOriginCount,cohorts,command_count:commands.length,failed_commands:commands.filter(c=>!c.passed).map(c=>c.name),all_owned_groups_retired:true,source_maps_equal:true,environment_maps_equal:true,test_root_equal:true,installed_versions:env.installed_count,all_versions_match_lock:env.all_versions_match_frozen_lock,scope:"Readout of original finite receipts only; no new project execution or qualification"};
}
function auditFollowupContinuation(get, codec, treeHash, config, prior) {
  const audited=auditFollowupFiniteReadout(get,codec,treeHash);
  const check=(value,message)=>{if(!value)throw Error(message)};
  const sorted=v=>v&&typeof v==="object"?(Array.isArray(v)?v.map(sorted):Object.fromEntries(Object.keys(v).sort().map(k=>[k,sorted(v[k])]))):v;
  const equal=(a,b)=>JSON.stringify(sorted(a))===JSON.stringify(sorted(b));
  const source=JSON.parse(get("source-before.json"));
  const admission=JSON.parse(get("source-contract.json"));
  const finite=JSON.parse(get("finite-results.json"));
  const commands=JSON.parse(get("commands.json"));
  check(source.source_sha===config.source_sha&&source.source_tree===config.source_tree,"exact follow-up source");
  check(source.source_parent===config.source_parent,"exact source parent");
  check(admission.passed===true&&admission.whole_source_seven_file_inverse===true,"current source inverse");
  check(admission.unchanged_other_files===4553&&Object.keys(source.files).length===4560,"complete source count");
  check(equal(admission.original_run,config.original_run),"original run binding");
  check(equal(finite.original_failed_run,config.original_run),"retained original failed run");
  check(prior.original_counts.passed===157&&prior.original_counts.failed===12,"original failed result remains");
  check(prior.source_sha===config.source_parent&&prior.source_tree===config.source_parent_tree,"original case source");
  const oldCases=new Map(prior.original_cases.map(x=>[x.nodeid,x]));
  const selected=new Map(config.selected_original_cases.map(x=>[x.nodeid,x]));
  const retained=[...oldCases.keys()].filter(n=>!selected.has(n)).sort();
  check(retained.length===152&&selected.size===17,"exact continuation split");
  check(equal(retained,admission.retained_prior_passing_cases)&&equal(retained,finite.retained_prior_passing_cases),"retained 152 case census");
  check(retained.every(n=>oldCases.get(n).outcome==="passed"),"only previous passes retained");
  check([...selected.keys()].filter(n=>oldCases.get(n).outcome==="failed").length===12,"all previous failures selected");
  check(admission.retained_prior_case_ast_equal===true&&admission.candidate_fixture_definition_asts_equal===true,"source/fixture AST proof");
  check(admission.current_product_bridges.writer_complete_ast_equal===true&&admission.current_product_bridges.witness_only_module_docstring_changed===true&&admission.current_product_bridges.gate_exact_short_circuit_order_and_body_preserved===true,"bounded product bridges");
  check(admission.actual_original_command_helper_users.length===11&&admission.actual_original_weakref_users.length===4,"actual original AST census");
  check([...admission.actual_original_command_helper_users,...admission.actual_original_weakref_users].every(n=>selected.has(n)&&oldCases.get(n).outcome==="failed"),"changed-provider callers selected");
  const depBefore=get("dependency-contract-before.json"),depAfter=get("dependency-contract-after.json");
  check(depBefore===depAfter,"dependency fixture bytes changed");
  const dep=JSON.parse(depBefore);
  check(dep.passed===true&&dep.fixture_complete_file_and_ast_hashes_equal_to_original===true&&dep.fixture_records.length===4,"four current owned fixture definitions");
  check(new Set(dep.fixture_records.map(r=>r.path)).size===3,"three current dependency files");
  for(const cohort of config.cohorts){
    const cap=JSON.parse(get(cohort.name+"/pytest-capture.json"));
    check(cap.original_contract_current_source_comparison_passed===true,"current collection guard");
    check(equal(cap.collection,admission.expected_followup_collections[cohort.name]),"exact current complete collection rows");
    check(equal(cap.collection.map(x=>x.nodeid),cohort.selectors),"exact selected node order");
  }
  check(audited.actual_cases===17&&audited.actual_phases===51,"actual 17-case/51-phase scope");
  check(finite.compiler.actual_callback_controls_executed===0&&finite.compiler.actual_callback_cases.length===0,"no callback body replay");
  check(finite.compiler.actual_build_receipt.compilation.length===2,"two original C session builds");
  check(finite.compiler.original_callback_controls.cases===10&&finite.compiler.original_callback_controls.replayed_in_followup===false,"old ten controls remain old");
  const names=["source-contract","uv-version","create-validation-environment","frozen-project-install","dependency-compatibility","environment-before","dependency-contract-before","ruff-version","basedpyright-version","compiler-version","ruff-check-13","ruff-format-check-13","basedpyright-production","basedpyright-diagnostic","source-gate-0","source-gate-1","source-gate-2","finite-writer-queue","finite-sqlite-vfs","dependency-contract-after","environment-after"];
  check(equal(commands.map(x=>x.name),names),"exact finite command ledger");
  check(commands.filter(x=>x.name.startsWith("finite-")).every(x=>x.timeout_seconds===300),"unchanged cohort caps");
  check(finite.fresh_169_case_execution===false&&admission.fresh_169_case_execution===false,"no fresh169 pooling");
  const build=finite.compiler.actual_build_receipt;
  const capture=JSON.parse(get("sqlite-vfs/pytest-capture.json"));
  check(capture.compiled_build_directories.length===1,"one C session fixture");
  const root="sqlite-vfs/compiled-build/"+capture.compiled_build_directories[0]+"/";
  for(let i=0;i<2;i++)check(equal(JSON.parse(get(root+"compile-"+i+".json")),build.compilation[i]),"retained compiler commands");
  check(build.compilation.every(x=>x.returncode===0&&!x.argv.includes("-lsqlite3")),"actual Python engine extension build");
  return {...audited,original_failed_run:config.original_run,source_fixture_provider_bridge_passed:true,
    historical_unaffected_passes:152,fresh_cases:17,fresh_169_case_execution:false,
    compiler_session_commands:2,callback_controls_replayed:0,original_callback_controls:10,
    scope:"Readout of this single original follow-up attempt. Historical 152 plus fresh 17 remain separately attributed; no installed/kernel/physical/PRD qualification."};
}

