function indexRsp131FollowupFrames(log, expectedSource, expectedHarness, expectedRun) {
  const prefix = "RSP131_SQLITE_QUEUE_FOLLOWUP_V1";
  const frames = [];
  const ignored = [];
  let active = null;
  let count = null;
  let outcome = null;
  let bomPrefixes = 0;
  let rawTotal = 0;
  let compressedTotal = 0;
  if (typeof log !== "string" || log.length > 64 * 1024 * 1024) throw Error("Original log bound");
  for (const original of log.split(/\r?\n/)) {
    let line = original;
    if (/^\uFEFF\d{4}-\d{2}-\d{2}T[0-9:.]+Z /.test(line)) {
      line = line.slice(1);
      bomPrefixes++;
    }
    line = line.replace(/^\d{4}-\d{2}-\d{2}T[0-9:.]+Z /, "");
    if (!line.startsWith(prefix + " ")) continue;
    if (line.startsWith(prefix + " BEGIN ")) {
      if (active || outcome) throw Error("Nested or post-outcome frame");
      const rawHeader = line.slice((prefix + " BEGIN ").length);
      const header = JSON.parse(rawHeader);
      if (!Number.isInteger(header.index) || header.index !== frames.length + 1 ||
          !Number.isInteger(header.count) || header.count < 1 || header.count > 256) throw Error("Frame order/count");
      if (count !== null && count !== header.count) throw Error("Changed frame population");
      count = header.count;
      if (typeof header.path !== "string" || !header.path || header.path.length > 256 ||
          header.path.startsWith("/") || header.path.split("/").some(part => part === ".." || part === "") ||
          frames.some(frame => frame.header.path === header.path)) throw Error("Frame path");
      for (const key of ["raw_bytes", "gzip_bytes", "original_bytes", "base64_characters", "parts"]) {
        if (!Number.isInteger(header[key]) || header[key] < 0) throw Error("Invalid frame size");
      }
      if (header.raw_bytes > 16 * 1024 * 1024 || header.original_bytes > 16 * 1024 * 1024 ||
          header.gzip_bytes > 2 * 1024 * 1024 || header.parts < 1 ||
          header.base64_characters !== Math.ceil(header.gzip_bytes / 3) * 4 ||
          header.parts !== Math.ceil(header.base64_characters / 6000)) throw Error("Frame bounds");
      for (const key of ["raw_sha256", "gzip_sha256", "original_sha256"]) {
        if (!/^[0-9a-f]{64}$/.test(header[key])) throw Error("Invalid SHA256 field");
      }
      if (!["utf-8", "base64-json-envelope"].includes(header.encoding)) throw Error("Encoding");
      rawTotal += header.raw_bytes;
      compressedTotal += header.gzip_bytes;
      if (rawTotal > 64 * 1024 * 1024 || compressedTotal > 8 * 1024 * 1024) throw Error("Aggregate bound");
      active = {header, rawHeader, parts: []};
    } else if (line.startsWith(prefix + " PART ")) {
      const match = line.match(/^RSP131_SQLITE_QUEUE_FOLLOWUP_V1 PART ([1-9][0-9]*) ([1-9][0-9]*)\/([1-9][0-9]*) ([A-Za-z0-9+/=]+)$/);
      if (!active || !match || Number(match[1]) !== active.header.index ||
          Number(match[2]) !== active.parts.length + 1 || Number(match[3]) !== active.header.parts) throw Error("Part order");
      const part = match[4];
      if (part.length > 6000 || (Number(match[2]) < Number(match[3]) && part.length !== 6000)) throw Error("Part length");
      active.parts.push(part);
    } else if (line.startsWith(prefix + " END ")) {
      if (!active || line.slice((prefix + " END ").length) !== active.rawHeader ||
          active.parts.length !== active.header.parts) throw Error("Frame end mismatch");
      const base64 = active.parts.join("");
      if (base64.length !== active.header.base64_characters || base64.length % 4 !== 0 ||
          !/^[A-Za-z0-9+/]*={0,2}$/.test(base64)) throw Error("Base64 extent");
      frames.push({header: active.header, base64});
      active = null;
    } else if (line.startsWith(prefix + " OUTCOME ")) {
      if (active || outcome) throw Error("Unexpected outcome position");
      outcome = JSON.parse(line.slice((prefix + " OUTCOME ").length));
      if (outcome.source_sha !== expectedSource || outcome.harness_sha !== expectedHarness ||
          outcome.run_id !== String(expectedRun) || outcome.run_attempt !== "1" ||
          outcome.qualification_complete !== false) throw Error("Outcome source/run binding");
    } else {
      ignored.push(line);
      throw Error("Unrecognized framed record");
    }
  }
  if (active) throw Error("Incomplete final frame");
  if (!outcome) throw Error("Original projection outcome absent");
  if (outcome.passed !== true) return {frames, outcome, complete: false, bomPrefixes,
      rawTotal, compressedTotal, failure: "Original projection failed; retained originals require separate recovery"};
  if (count !== frames.length || outcome.frames.length !== frames.length ||
      outcome.raw_bytes !== rawTotal || outcome.gzip_bytes !== compressedTotal) throw Error("Final frame inventory");
  for (let index = 0; index < frames.length; index++) {
    const {index: number, count: total, ...record} = frames[index].header;
    if (JSON.stringify(record) !== JSON.stringify(outcome.frames[index])) {
      const keys = Object.keys(record).sort();
      if (JSON.stringify(keys) !== JSON.stringify(Object.keys(outcome.frames[index]).sort()) ||
          keys.some(key => record[key] !== outcome.frames[index][key])) throw Error("Frame metadata differs from outcome");
    }
  }
  return {frames, outcome, complete: true, bomPrefixes, rawTotal, compressedTotal};
}
